fn fill(v: &mut Vec[Int], count: Int) -> Unit {
  v.clear();
  var i = 0;
  while i < count {
    v.push(i);
    i = i + 1;
  }
}

fn rotate_left(v: &mut Vec[Int]) -> Unit {
  if v.len() <= 1 { return; }
  let first = v[0];
  var i = 0;
  while i < v.len() - 1 {
    v[i] = v[i + 1];
    i = i + 1;
  }
  v[v.len() - 1] = first;
}

fn main() -> Int {
  var v = Vec[Int]();
  v.push(1); v.push(2); v.push(3); v.push(4);
  rotate_left(&mut v);
  return v[0];
}
